git diff --stat HEAD
git ls-files --others --exclude-standard

# For branch diff:
git diff --stat <branch>...HEAD

# For specific commit:
git d','.claude\skills\second-opinion\SKILL.md','3c6627a1362cbaab10a3401962d9b1f5443bcc404c67ff7d8742cc281694f8c1','skill,simplicio,coding',1.3);
