llm = Llama(
    model_path="./model-q4_k_m.gguf",
    n_ctx=4096,
    n_gpu_layers=35,     # 0 for CPU, 99 ','skills\mlops\inference\llama-cpp\SKILL.md','5bc12764489046be37473418acca1dc8b306132679632fd04798bab674c57418','skill,simplicio,orchestration',1.3);
