class Sentiment(str, Enum):
    POSITIVE = "positive"
    NEGATIVE = "negative"
    NEUT','skills\mlops\instructor\SKILL.md','adf6964496eb14b886766e0ff0333a9a228fc9e30b6c5e38e759da09f731d4d4','skill,simplicio,orchestration',1.3);
